import{z as l,x as i,o as A,c as d,q as r,j as n,D as B,d as a,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const N=JSON.parse('{"title":"知识管理","description":"","frontmatter":{"title":"知识管理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sl-knowledge-management.md","filePath":"quant/sl-knowledge-management.md","lastUpdated":1791063341000}'),D={name:"quant/sl-knowledge-management.md"};function C(p,E,m,h,u,f){const t=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="知识管理" tabindex="-1">知识管理 <a class="header-anchor" href="#知识管理" aria-label="Permalink to &quot;知识管理&quot;">​</a></h1><div class="epigraph"><p>负结果若不可检索，组织就会一遍遍把钱花在同一口井上：内部知识的幸存者偏差，与样本的幸存者偏差同样致命。</p><footer>—— 据 Arnott, Harvey and Markowitz, *Journal of Financial Data Science*, 2019 与内部复盘规范整理</footer></div><p><a href="/quant/sl-exit-mechanism">上一课</a>把策略死成台账里的一行，退役完成。本课写这一行如何变成组织的记忆。研究复盘课已经立了四件沉淀物——假设台账、失败清单、可复现快照、带迁移条件的一页案例；本课把它们接进生命周期：每一次阶段转移都产生必须沉淀的对象，知识管理是生命周期的闭环，不是额外的文档工作。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组织遗忘有三个具体机制。人走了知识走：判据为什么那样设、当年否掉的方案是什么，只活在离开者的脑子里。信号换包装再来：三年前死掉的思路改个名字重新立项，\\(N\\) 从零起算——多重检验保护在组织层面失灵，回测过的<a href="/quant/backtest-overfitting">过拟合算术</a>对团队内部同样成立。成功被讲述、失败失踪：内部案例库里全是活下来的策略，新人的「历史经验」自带虚高的夏普，与数据里的幸存者偏差同构。三者共同的缺口是：把个体经验变成可检索的共享资产，并且让检索行为本身进治理——查过失败库是立项的前置条件，而不是美德。</p><p><span class="marginnote">直觉类比：只看公司里活下来的策略学做研究，像只采访中奖者学买彩票——样本里全是赢家的故事。失败库的作用是把「没中的彩票」也摆上货架，新人的历史先验才不至于自带虚高的夏普。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>知识资产与台账同构：<strong>一策略一卷宗</strong>，随阶段转移增量成卷——判据引用、\\(N\\) 与累计范围、容量与衰减声明、批准与驳回记录、复盘、退出案例；退役转移是卷宗完整性的强制检查点，不完整不允许置退役状态。<strong>失败库按死因索引</strong>：判据未过、漂移、拥挤、合规、操作，死因必须落在判据上——「效果不好」不是索引项，<a href="/quant/research-postmortem">复盘课的口径</a>照搬。<strong>立项前置检查</strong>：新提案必须附相似检索结果——查过什么、为何不同；检索记录本身入卷宗，让「不知道已有失败」不再是无责借口。<strong>谱系 \\(N\\) 累计</strong>：同谱系的重复试验累加，检索是计数的入口，\\(N\\) 从此不清零。</p><p><span class="marginnote">术语翻译：谱系 \\(N\\) 就是「这个思路加上它的变体总共被认真试过几次」的计数。同一想法改参数、改宇宙、改名字都算同谱系——计数跟着思路走而不是跟着立项书走，\\(N\\) 不清零，多重检验的账才算得对。</span></p>',9)),(A(),n(o,null,{default:B(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRANS%5B%22%E9%98%B6%E6%AE%B5%E8%BD%AC%E7%A7%BB%22%5D%20--%3E%20DOSSIER%5B%22%E5%8D%B7%E5%AE%97%E5%A2%9E%E9%87%8F%EF%BC%9A%E5%88%A4%E6%8D%AE%E3%80%81N%E3%80%81%E5%A3%B0%E6%98%8E%E3%80%81%E8%AE%B0%E5%BD%95%22%5D%0A%20%20RETIRE%5B%22%E9%80%80%E5%BD%B9%E8%BD%AC%E7%A7%BB%22%5D%20--%3E%20CHECK%7B%22%E5%8D%B7%E5%AE%97%E5%AE%8C%E6%95%B4%E6%80%A7%E6%A3%80%E6%9F%A5%22%7D%0A%20%20CHECK%20--%3E%7C%E4%B8%8D%E5%AE%8C%E6%95%B4%7C%20BACK%5B%22%E6%8B%92%E7%BB%9D%E7%BD%AE%E9%80%80%E5%BD%B9%EF%BC%9A%E8%A1%A5%E5%8D%B7%22%5D%0A%20%20CHECK%20--%3E%7C%E5%AE%8C%E6%95%B4%7C%20KM%5B%22%E5%BD%92%E6%A1%A3%EF%BC%9A%E5%8D%B7%E5%AE%97%E4%B8%8E%E5%A4%B1%E8%B4%A5%E5%BA%93%E5%8F%AF%E6%A3%80%E7%B4%A2%22%5D%0A%20%20PROPOSE%5B%22%E6%96%B0%E6%8F%90%E6%A1%88%22%5D%20--%3E%20SEARCH%5B%22%E6%A3%80%E7%B4%A2%E5%A4%B1%E8%B4%A5%E5%BA%93%E4%B8%8E%E8%B0%B1%E7%B3%BB%22%5D%0A%20%20SEARCH%20--%3E%20NCOUNT%5B%22%E8%B0%B1%E7%B3%BB%20N%20%E7%B4%AF%E5%8A%A0%EF%BC%8C%E4%B8%8D%E6%B8%85%E9%9B%B6%22%5D%0A%20%20NCOUNT%20--%3E%20NEW%5B%22%E6%96%B0%E8%AF%95%E9%AA%8C%EF%BC%9A%E8%B5%B0%E7%89%88%E6%9C%AC%E4%B8%8E%E5%AE%A1%E6%89%B9%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("知识库必须挂在台账上而不是靠自觉归档，原因是制度由状态机强制而非由记忆维持：阶段转移是天然的归档触发器，人在最掌握上下文的时刻被要求写下来，拖延的空间被状态机没收。检索前置改变的是提案的先验：带着「已有三次失败」的先验去设计试验，与从零自信出发，是两个不同的研究。谱系累计则是组织层面的多重检验防线——它与"),e("a",{href:"/quant/deflated-sharpe"},"缩减统计量"),a("的个体层面防线互补：个体防止一次试验里挑最好的，组织防止同一口井被反复挖。复盘的三条制度——复盘免责、案例同权、快照双冻结——在这里成为入库标准：免责保证写真话，案例同权保证失败入库与成功同等待遇，双冻结保证卷宗在多年后仍可复现。")],-1)),(A(),n(o,null,{default:B(()=>[s(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E4%B8%89%E5%B9%B4%E5%89%8D%E6%AD%BB%E6%8E%89%E7%9A%84%E6%80%9D%E8%B7%AF%22%5D%20--%3E%20RENAME%5B%22%E6%8D%A2%E4%B8%AA%E5%90%8D%E5%AD%97%E9%87%8D%E6%96%B0%E7%AB%8B%E9%A1%B9%22%5D%0A%20%20RENAME%20--%3E%20SEARCH%7B%22%E7%AB%8B%E9%A1%B9%E5%89%8D%E7%BD%AE%E7%9B%B8%E4%BC%BC%E6%A3%80%E7%B4%A2%22%7D%0A%20%20SEARCH%20--%3E%7C%22%E5%91%BD%E4%B8%AD%E8%B0%B1%E7%B3%BB%22%7C%20NACC%5B%22%E8%B0%B1%E7%B3%BB%20N%20%E7%B4%AF%E5%8A%A0%EF%BC%9A%E4%B8%8D%E6%B8%85%E9%9B%B6%22%5D%0A%20%20SEARCH%20--%3E%7C%22%E7%A1%AE%E5%AE%9E%E4%B8%8D%E5%90%8C%22%7C%20NEWV%5B%22%E6%96%B0%E8%AF%95%E9%AA%8C%EF%BC%9A%E8%B5%B0%E7%89%88%E6%9C%AC%E4%B8%8E%E5%AE%A1%E6%89%B9%22%5D%0A%20%20NACC%20--%3E%20DS%5B%22%E7%BC%A9%E5%87%8F%E7%BB%9F%E8%AE%A1%E9%87%8F%EF%BC%9A%E6%8C%89%E7%B4%AF%E8%AE%A1%20N%20%E6%8A%98%E5%87%8F%E5%A4%8F%E6%99%AE%22%5D%0A%20%20DS%20--%3E%20BAR%5B%22%E5%A4%9A%E9%87%8D%E6%A3%80%E9%AA%8C%E4%BF%9D%E6%8A%A4%E5%9C%A8%E7%BB%84%E7%BB%87%E5%B1%82%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">跨团队 \\(N\\) 累计的最小实现：卷宗对外只暴露谱系标签、判据引用与死因三元组，参数与快照留在权限内——计数可见而细节不可见，多重检验的保护与策略保密可以同时成立。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>知识库不自动产生智慧：入库门槛太高则无人入库，太低则检索被噪声淹没——一页案例的强制格式是折中，写不完一页的失败通常还没落到判据上。保密与共享有张力：只共享谱系与死因的元数据，不共享参数，是本课给的解，代价是偶尔错过「参数不同但机制相同」的判同——这个错要认。不复述复盘的写作格式与免责条款设计，那是<a href="/quant/research-postmortem">复盘课</a>的内容。知识管理管的是生命周期产生的记忆；团队里谁写、谁审、谁在会上用这些卷宗，是下一课团队流程的对象。</p><p><span class="marginnote">常见误区：初学者容易以为知识库越全越好、什么都要往里放。入库门槛太高则没人写，太低则检索被噪声淹没——写不完一页的失败通常还没落到判据上。知识管理的目标是可检索的好先验，不是归档数量的大赛。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一策略一卷宗，随阶段转移增量成卷；退役转移强制卷宗完整性检查。</li><li>失败库按死因索引，死因必须落在判据上；负结果可检索才没有内部幸存者偏差。</li><li>立项前置相似检索，检索记录入卷宗；谱系 \\(N\\) 累计、永不清零。</li><li>复盘免责、案例同权、快照双冻结，是卷宗可信的三个制度前提。</li><li>出处：Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019；沉淀物四件与复盘制度见<a href="/quant/research-postmortem">研究复盘</a>；多重检验保护见<a href="/quant/deflated-sharpe">缩减夏普</a>。</li></ul>',6))])}const g=l(D,[["render",C]]);export{N as __pageData,g as default};
